contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint minSum, address logAddr) public payable {
        require(true);

        // Before initialization, set observable state.
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.SetLogFile(logAddr); if (__ESBMC_reverted()) return;

        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        // First initialization: must not revert and must enable the permanent lock.
        bool firstReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }

        // Capture the value after the first initialization.
        uint afterFirstMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        // Second initialization: must not revert and must leave state unchanged.
        bool secondReverted;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }

        uint afterSecondMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(
            !firstReverted &&
            !secondReverted &&
            afterFirstMinSum == beforeMinSum &&
            afterSecondMinSum == afterFirstMinSum
        );
    }

    receive() external payable {}
}

